function playSound(kind){if(!soundEnabled)return;try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;audioContext=audioContext||new Audio();if(audioContext.state==='suspended')audioContext.resume();const now=audioContext.currentTime,osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type=kind==='hit'?'triangle':kind==='spell'?'sine':'square';osc.frequency.setValueAtTime(kind==='hit'?170:kind==='spell'?480:340,now);osc.frequency.exponentialRampToValueAtTime(kind==='hit'?90:kind==='spell'?720:260,now+.13);gain.gain.setValueAtTime(kind==='hit'?.11:.045,now);gain.gain.exponentialRampToValueAtTime(.001,now+(kind==='hit'?.22:.17));osc.connect(gain);gain.connect(audioContext.destination);osc.start(now);osc.stop(now+.18)}catch(e){console.warn('Sound unavailable',e)}}
function playMiss(kind='melee',critical=false){
 if(!soundEnabled)return;
 try{
  const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;
  audioContext=audioContext||new Audio();if(audioContext.state==='suspended')audioContext.resume();
  const now=audioContext.currentTime;
  // Melee: airy descending whoosh. Spell: hollow dissipating shimmer.
  // Critical failures have a slightly longer, lower-pitched finish.
  const notes=kind==='spell'?
    [['sine',610,205,.060,0,.18],['triangle',880,340,.027,.045,critical?.29:.19]]:
    [['sawtooth',310,110,.048,0,.13],['triangle',225,75,.032,.045,critical?.25:.14]];
  for(const [type,from,to,volume,delay,duration] of notes){
   const osc=audioContext.createOscillator(),gain=audioContext.createGain(),t=now+delay;
   osc.type=type;osc.frequency.setValueAtTime(from,t);osc.frequency.exponentialRampToValueAtTime(to,t+duration);
   gain.gain.setValueAtTime(.0001,t);gain.gain.linearRampToValueAtTime(volume,t+.012);
   gain.gain.exponentialRampToValueAtTime(.0001,t+duration);
   osc.connect(gain);gain.connect(audioContext.destination);osc.start(t);osc.stop(t+duration+.015);
  }
 }catch(e){console.warn('Miss sound unavailable',e)}
}
function playCriticalHit(){
 if(!soundEnabled)return;
 try{
  const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;
  audioContext=audioContext||new Audio();if(audioContext.state==='suspended')audioContext.resume();
  const now=audioContext.currentTime;
  // Original layered critical-hit sting: impact, low thump, and bright metallic finish.
  for(const [type,start,end,volume,delay,duration] of [
   ['sawtooth',340,68,.13,0,.20],['triangle',115,43,.19,.015,.29],
   ['square',1046.5,783.99,.045,.075,.17],['sine',1567.98,1174.66,.038,.115,.21]
  ]){
   const osc=audioContext.createOscillator(),gain=audioContext.createGain(),t=now+delay;
   osc.type=type;osc.frequency.setValueAtTime(start,t);osc.frequency.exponentialRampToValueAtTime(end,t+duration);
   gain.gain.setValueAtTime(.0001,t);gain.gain.linearRampToValueAtTime(volume,t+.009);
   gain.gain.exponentialRampToValueAtTime(.0001,t+duration);
   osc.connect(gain);gain.connect(audioContext.destination);osc.start(t);osc.stop(t+duration+.015);
  }
 }catch(e){console.warn('Critical hit audio unavailable',e)}
}
let endingMusicNodes=[];
function stopEndingMusic(){for(const node of endingMusicNodes){try{node.stop()}catch(e){}}endingMusicNodes=[]}
function playEndingMusic(outcome){
 if(!soundEnabled)return;
 try{
  const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;
  audioContext=audioContext||new Audio();if(audioContext.state==='suspended')audioContext.resume();
  stopEndingMusic();
  // Original, short melodies composed for Embers of the Vault; no external audio assets.
  const victory=[[392,0,.20],[523.25,.21,.20],[659.25,.42,.20],[783.99,.63,.34],[659.25,1.02,.15],[783.99,1.20,.18],[1046.5,1.42,.58]];
  const defeat=[[392,0,.32],[369.99,.35,.32],[311.13,.70,.37],[261.63,1.12,.50],[196,1.68,.76]];
  const notes=outcome==='victory'?victory:defeat,now=audioContext.currentTime+.035;
  for(const [frequency,offset,duration] of notes){
   const osc=audioContext.createOscillator(),gain=audioContext.createGain();
   osc.type=outcome==='victory'?'triangle':'sine';osc.frequency.setValueAtTime(frequency,now+offset);
   gain.gain.setValueAtTime(.0001,now+offset);
   gain.gain.linearRampToValueAtTime(.085,now+offset+.025);
   gain.gain.setValueAtTime(.07,now+offset+Math.max(.04,duration-.09));
   gain.gain.exponentialRampToValueAtTime(.0001,now+offset+duration);
   osc.connect(gain);gain.connect(audioContext.destination);
   osc.start(now+offset);osc.stop(now+offset+duration+.02);endingMusicNodes.push(osc);
  }
 }catch(e){console.warn('Ending music unavailable',e)}
}
