function choicesAt(level,classId=campaign.classId){if(classId==='wizard'&&wizardPaths[level])return wizardPaths[level].map((o,i)=>({id:i?'b':'a',name:o[0],stat:o[1],amount:o[2],description:o[3]}));if(classId==='cleric'&&clericPaths[level])return clericPaths[level].map((o,i)=>({id:i?'b':'a',name:o[0],stat:o[1],amount:o[2],description:o[3]}));if(martialPaths[classId]?.[level])return martialPaths[classId][level].map((o,i)=>({id:i?'b':'a',name:o[0],stat:o[1],amount:o[2],description:o[3]}));if(['fighter','rogue'].includes(classId)&&(level===3||level===5)){const names=classId==='fighter'?(level===3?['Shield Bash','Sweeping Strike']:['Sundering Blow','Rallying Strike']):(level===3?['Dirty Trick','Twin Cut']:['Shadow Strike','Bleeding Cut']);return names.map((name,i)=>({id:i?'b':'a',name,stat:'technique',amount:level}))}if(['wizard','cleric'].includes(classId)&&(level===3||level===5)){const names=classId==='wizard'?(level===3?['Arcane Lance','Frost Lance']:['Storm Lance','Flame Lance']):(level===3?['Divine Lance','Sunfire']:['Judgment','Sacred Flame']);return names.map((name,i)=>({id:i?'b':'a',name,stat:'spell',amount:level===3?1:2,description:spellDescriptions[name]}))}const names=levelPaths[classId]?.[level-1]?.split('|')||[];return names.map((name,i)=>({id:i?'b':'a',name,stat:i?(level%2?(['wizard','cleric'].includes(classId)?'spellDamage':'damage'):(['wizard','cleric'].includes(classId)?'spellAttack':'attack')):(level%2?'hp':'ac'),amount:i?(level%2?2:1):(level%2?5:1)}))}
