function updateBlastPreview(){const u=current();if(!u)return;const range=targetRange(u),spell=mode.startsWith('spell')?learnedSpells().find(o=>'spell'+o.level===mode):null,radius=mode==='bomb'||mode==='blast'?1:({'Flame Burst':2,'Thunderstorm':3,'Meteor Shower':4,'Arcane Cataclysm':5}[spell?.name]||0);for(const tile of $('board').querySelectorAll('[data-x]')){const x=+tile.dataset.x,y=+tile.dataset.y,wall=terrain.has(x+','+y),valid=range>0&&!wall&&dist(u,{x,y})<=range,preview=hoveredTarget&&radius&&areaDistance({x,y},hoveredTarget)<=radius;tile.setAttribute('fill',wall?'#675d58':preview?'#b7443f':valid?'#71353d':(x+y)%2?'#344553':'#3b4d5b')}}
