function checkEnd(){if(finished)return;if(!units.some(v=>v.team==='ally'&&alive(v))){finished=true;busy=false;say('<strong>DEFEAT.</strong> The party retreats to camp.');playEndingMusic('defeat');failEncounter()}else if(units.filter(v=>v.team==='enemy').every(v=>!alive(v))){finished=true;busy=false;say('<strong>VICTORY!</strong> Encounter cleared.');playEndingMusic('victory');completeEncounter()}render()}
