function advanceDead(){while(!finished&&!alive(current())){turn++;if(turn>=order.length){round++;for(const v of units){if(v.attackBuffRounds){v.attackBuffRounds--;if(!v.attackBuffRounds)v.attackBuff=0}if(v.wardRounds)v.wardRounds--}rollInitiative();turn=0}}}
