function shortestStep(u,target){let q=[[u.x,u.y]],seen=new Set([`${u.x},${u.y}`]),parent=new Map(),found=null;for(let i=0;i<q.length;i++){let [x,y]=q[i];if(Math.abs(x-target.x)+Math.abs(y-target.y)===1){found=[x,y];break}for(let [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){let nx=x+dx,ny=y+dy,k=`${nx},${ny}`;if(!inside(nx,ny)||seen.has(k)||unitAt(nx,ny))continue;seen.add(k);parent.set(k,`${x},${y}`);q.push([nx,ny])}}if(!found)return null;let key=found.join(',');while(parent.has(key)&&parent.get(key)!==`${u.x},${u.y}`)key=parent.get(key);let [x,y]=key.split(',').map(Number);return {x,y}}
